-- KarnatakaDBT simulation schema 1.0.0; not a government production DDL
CREATE TABLE schemes(scheme_id TEXT PRIMARY KEY, name TEXT NOT NULL, rule_version TEXT NOT NULL, audience TEXT NOT NULL CHECK(audience IN ('household','farmer','student')), monthly_income_ceiling_inr INTEGER NOT NULL CHECK(monthly_income_ceiling_inr>=0), benefit_minor INTEGER NOT NULL CHECK(benefit_minor>0), currency TEXT NOT NULL CHECK(currency='INR'), required_sources TEXT NOT NULL);
 CREATE TABLE sanctions(sanction_id TEXT PRIMARY KEY, run_id TEXT UNIQUE NOT NULL, household_ref TEXT NOT NULL, scheme_id TEXT NOT NULL REFERENCES schemes(scheme_id), cycle TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(amount_minor>0), status TEXT NOT NULL CHECK(status='sanctioned'), UNIQUE(household_ref,scheme_id,cycle));